-- Script gerado pelo Map Exporter
-- Reconstrói uma cópia das partes exportadas

-- Deleta a pasta de barreiras invisíveis do mapa original, se existir
local invisibleWalls = workspace:FindFirstChild("InvisibleCollisionWalls")
if invisibleWalls then
	invisibleWalls:Destroy()
end

local folder = workspace:FindFirstChild("RebuiltMap")

if folder then
	folder:ClearAllChildren()
else
	folder = Instance.new("Folder")
	folder.Name = "RebuiltMap"
	folder.Parent = workspace
end

local function safeMaterial(materialName)
	local success, material = pcall(function()
		return Enum.Material[materialName]
	end)

	if success and material then
		return material
	end

	return Enum.Material.Plastic
end

local function safeShape(shapeName)
	if not shapeName or shapeName == "" then
		return nil
	end

	local success, shape = pcall(function()
		return Enum.PartType[shapeName]
	end)

	if success and shape then
		return shape
	end

	return nil
end

local function build(data)
	for _, d in ipairs(data) do
		local className = d[1]
		local part

		-- MeshPart é convertido para Part + SpecialMesh
		-- para evitar falhas ao criar MeshPart diretamente.
		if d[11] and d[11] ~= "" then
			part = Instance.new("Part")

			local mesh = Instance.new("SpecialMesh")
			mesh.MeshType = Enum.MeshType.FileMesh
			mesh.MeshId = d[11]

			if d[12] and d[12] ~= "" then
				mesh.TextureId = d[12]
			end

			mesh.Parent = part
		else
			local success, result = pcall(function()
				return Instance.new(className)
			end)

			if success and result then
				part = result
			else
				part = Instance.new("Part")
			end
		end

		part.Name = d[2]

		part.Size = Vector3.new(
			tonumber(d[3][1]) or 1,
			tonumber(d[3][2]) or 1,
			tonumber(d[3][3]) or 1
		)

		part.CFrame = CFrame.new(table.unpack(d[4]))

		part.Color = Color3.fromRGB(
			tonumber(d[5][1]) or 255,
			tonumber(d[5][2]) or 255,
			tonumber(d[5][3]) or 255
		)

		part.Material = safeMaterial(d[6])
		part.CanCollide = d[7] == true
		part.Transparency = math.clamp(tonumber(d[8]) or 0, 0, 1)
		part.Reflectance = math.clamp(tonumber(d[9]) or 0, 0, 1)
		part.CastShadow = d[10] == true
		part.Anchored = true

		-- Shape só existe diretamente em Part.
		if part:IsA("Part") then
			local shape = safeShape(d[13])

			if shape then
				part.Shape = shape
			end
		end

		part.Parent = folder
		
		-- Atribui o grupo diretamente pelo ID 5 (MainObject)
		part.CollisionGroupId = 5
	end
end

